382		if err = tx.Commit(); err != nil {
383			return fmt.Errorf("commit transaction: %w", err)
384		}
385		return nil
386	}
387	
388	// RefreshFromInsightsDB checks if the cache is stale and repopulates if needed.
389	// Returns true if the cache was refreshed.
390	func (sdb *SkillDB) RefreshFromInsightsDB(ctx context.Context, idb *insightsdb.InsightsDB, discoveredSkills []SkillRow, repoRoot string) (bool, error) {
391		// Check insightsdb branch tip with cache version prefix.
392		// Bumping cacheVersion forces re-population even if the branch tip hasn't changed,
393		// e.g. after fixing the skill name matching logic.
394		currentTip, err := idb.GetBranchTip(ctx)
395		if err != nil {
396			return false, fmt.Errorf("get insightsdb branch tip: %w", err)
397		}
398	
399		versionedTip := cacheVersion + ":" + currentTip
400	
401		cachedTip, err := sdb.GetCacheTip(ctx)
402		if err != nil {
403			return false, fmt.Errorf("get skilldb cache tip: %w", err)
404		}
405	
406		if versionedTip != "" && versionedTip == cachedTip {
407			return false, nil
408		}
409	
410		// Upsert discovered skills.
411		now := time.Now().UTC()
412		for _, skill := range discoveredSkills {
413			if err = sdb.UpsertSkill(ctx, SkillRow{
414				Name:         skill.Name,
415				SourceAgent:  skill.SourceAgent,
416				Path:         skill.Path,
417				Kind:         skill.Kind,
418				DiscoveredAt: now,
419				LastSeenAt:   now,
420			}); err != nil {
421				return false, fmt.Errorf("upsert skill %q: %w", skill.Name, err)
422			}
423		}
424	
425		// Clear existing session data before repopulating.
426		if err = sdb.clearSessionData(ctx); err != nil {
427			return false, fmt.Errorf("clear session data: %w", err)
428		}
429	
430		// Populate from insightsdb.
431		if err = sdb.PopulateFromInsightsDB(ctx, idb, discoveredSkills, repoRoot); err != nil {
432			return false, fmt.Errorf("populate from insightsdb: %w", err)
433		}
434	
435		// Update cache tip with version prefix.
436		if versionedTip != "" {
437			if err = sdb.SetCacheTip(ctx, versionedTip); err != nil {
438				return false, fmt.Errorf("set cache tip: %w", err)
439			}
440		}
441	
442		return true, nil
443	}
444	
445	// clearSessionData removes all rows from session-related tables.
446	func (sdb *SkillDB) clearSessionData(ctx context.Context) error {
447		tables := []string{"skill_sessions", "skill_friction", "skill_missing_instructions"}
448		for _, table := range tables {
449			if _, err := sdb.db.ExecContext(ctx, "DELETE FROM "+table); err != nil { //nolint:gosec // table names are hardcoded
450				return fmt.Errorf("clear %s: %w", table, err)
451			}
452		}
453		return nil
454	}
455	
456	func extractSkillInvocationsFromTranscript(content []byte) ([]string, error) {
457		lines, err := transcript.ParseFromBytes(content)
458		if err != nil {
459			return nil, fmt.Errorf("parse transcript: %w", err)
460		}
461	
462		seen := make(map[string]bool)
463		var skills []string
464	
465		for _, line := range lines {
466			if line.Type != transcript.TypeAssistant {
467				continue
468			}
469	
470			var msg transcript.AssistantMessage
471			if err := json.Unmarshal(line.Message, &msg); err != nil {
472				continue
473			}
474	
475			for _, block := range msg.Content {
476				if block.Type != transcript.ContentTypeToolUse || block.Name != "Skill" {
477					continue
478				}
479	
480				var input transcript.ToolInput
481				if err := json.Unmarshal(block.Input, &input); err != nil {
482					continue
483				}
484	
485				skill := strings.TrimSpace(input.Skill)
486				if skill == "" || seen[skill] {
487					continue
488				}
489	
490				seen[skill] = true
491				skills = append(skills, skill)
492			}
493		}
494	
495		return skills, nil
496	}
