230	// discoverInPluginVersion finds skills, commands, and agent-defs in a plugin version directory.
231	func discoverInPluginVersion(versionDir string) []DiscoveredSkill {
232		var skills []DiscoveredSkill
233	
234		// Skills: {versionDir}/skills/{name}/SKILL.md
235		skillsDir := filepath.Join(versionDir, "skills")
236		if entries, err := os.ReadDir(skillsDir); err == nil {
237			for _, e := range entries {
238				if !e.IsDir() {
239					continue
240				}
241				skillFile := filepath.Join(skillsDir, e.Name(), "SKILL.md")
242				if _, err := os.Stat(skillFile); err == nil {
243					skills = append(skills, DiscoveredSkill{
244						Name:        e.Name(),
245						SourceAgent: "claude-code",
246						Path:        skillFile,
247						Kind:        "skill",
248						Scope:       ScopePlugin,
249					})
250				}
251			}
252		}
253	
254		// Commands: {versionDir}/commands/{name}.md
255		cmdsDir := filepath.Join(versionDir, "commands")
256		if matches, err := filepath.Glob(filepath.Join(cmdsDir, "*.md")); err == nil {
257			for _, match := range matches {
258				skills = append(skills, DiscoveredSkill{
259					Name:        strings.TrimSuffix(filepath.Base(match), ".md"),
260					SourceAgent: "claude-code",
261					Path:        match,
262					Kind:        "command",
263					Scope:       ScopePlugin,
264				})
265			}
266		}
267	
268		// Agent definitions: {versionDir}/agents/{name}.md
269		agentsDir := filepath.Join(versionDir, "agents")
270		if matches, err := filepath.Glob(filepath.Join(agentsDir, "*.md")); err == nil {
271			for _, match := range matches {
272				skills = append(skills, DiscoveredSkill{
273					Name:        strings.TrimSuffix(filepath.Base(match), ".md"),
274					SourceAgent: "claude-code",
275					Path:        match,
276					Kind:        "agent-def",
277					Scope:       ScopePlugin,
278				})
279			}
280		}
281	
282		return skills
283	}
284	
285	// extractYAMLName looks for a name field in YAML frontmatter delimited by "---".
286	func extractYAMLName(content string) string {
287		lines := strings.Split(content, "\n")
288		if len(lines) == 0 || strings.TrimSpace(lines[0]) != "---" {
289			return ""
290		}
291	
292		for _, line := range lines[1:] {
293			trimmed := strings.TrimSpace(line)
294			if trimmed == "---" {
295				break
296			}
297			if strings.HasPrefix(trimmed, "name:") {
298				value := strings.TrimPrefix(trimmed, "name:")
299				return strings.TrimSpace(value)
300			}
301		}
302	
303		return ""
304	}
