1	package insightsdb
2	
3	import (
4		"context"
5		"database/sql"
6		"fmt"
7		"strings"
8		"time"
9	
10		"github.com/entireio/cli/cmd/entire/cli/facets"
11	)
12	
13	// SessionRow represents a single session for insertion into the cache.
14	// This is the denormalized view used by the CLI — callers populate it
15	// from checkpoint.CommittedMetadata.
16	type SessionRow struct {
17		CheckpointID string
18		SessionID    string
19		SessionIndex int
20		Agent        string
21		Model        string
22		Branch       string
23		OwnerName    string
24		OwnerEmail   string
25		CreatedAt    time.Time
26		InputTokens  int
27		CacheTokens  int
28		OutputTokens int
29		TotalTokens  int
30		APICallCount int
31		DurationMs   int64
32		TurnCount    int
33		Intent       string
34		Outcome      string
35		AgentPct     float64
36		// Score fields
37		OverallScore   float64
38		ScoreTokenEff  float64
39		ScoreFirstPass float64
40		ScoreFriction  float64
41		ScoreFocus     float64
42		HasSummary     bool
43		HasFacets      bool
44		// Denormalized arrays
45		FilesTouched []string
46		Friction     []string
47		Learnings    []LearningRow
48		ToolCounts   map[string]int // tool name → invocation count
49		Facets       facets.SessionFacets
50	}
51	
52	// LearningRow represents a single learning entry within a session.
53	type LearningRow struct {
54		Scope   string // "repo", "workflow", "code"
55		Finding string
56		Path    string // only meaningful when Scope is "code"
57	}
58	
59	// GetBranchTip returns the stored branch tip hash from cache_meta,
60	// or an empty string if it has not been set yet.
61	func (idb *InsightsDB) GetBranchTip(ctx context.Context) (string, error) {
62		var tip string
63		err := idb.db.QueryRowContext(ctx,
64			"SELECT value FROM cache_meta WHERE key = ?",
65			"branch_tip",
66		).Scan(&tip)
67		if err == sql.ErrNoRows {
68			return "", nil
69		}
70		if err != nil {
71			return "", fmt.Errorf("get branch tip: %w", err)
72		}
73		return tip, nil
74	}
75	
76	// SetBranchTip stores the branch tip hash in cache_meta.
77	// Overwrites any previously stored value.
78	func (idb *InsightsDB) SetBranchTip(ctx context.Context, tip string) error {
79		_, err := idb.db.ExecContext(ctx,
80			"INSERT OR REPLACE INTO cache_meta (key, value) VALUES (?, ?)",
81			"branch_tip",
82			tip,
83		)
84		if err != nil {
85			return fmt.Errorf("set branch tip: %w", err)
86		}
87		return nil
88	}
89	
90	// HasCheckpoint returns true if any session for the given checkpoint ID
91	// is already present in the sessions table.
92	func (idb *InsightsDB) HasCheckpoint(ctx context.Context, checkpointID string) (bool, error) {
93		var count int
94		err := idb.db.QueryRowContext(ctx,
95			"SELECT COUNT(*) FROM sessions WHERE checkpoint_id = ?",
96			checkpointID,
97		).Scan(&count)
98		if err != nil {
99			return false, fmt.Errorf("check checkpoint existence: %w", err)
100		}
101		return count > 0, nil
102	}
103	
104	// InsertSession inserts a session and all its denormalized data into the cache.
105	// The insert is performed inside a single transaction so the cache remains
106	// consistent even if the caller is interrupted mid-insert.
107	func (idb *InsightsDB) InsertSession(ctx context.Context, row SessionRow) error {
108		tx, err := idb.db.BeginTx(ctx, nil)
109		if err != nil {
110			return fmt.Errorf("begin transaction: %w", err)
111		}
112		defer func() {
113			if err != nil {
114				_ = tx.Rollback() //nolint:errcheck // Rollback after failed tx; error is irrelevant
115			}
116		}()
117	
118		if err = insertSessionRow(ctx, tx, row); err != nil {
119			return err
120		}
121		if err = insertFilesTouched(ctx, tx, row); err != nil {
122			return err
123		}
124		if err = insertFriction(ctx, tx, row); err != nil {
125			return err
126		}
127		if err = insertLearnings(ctx, tx, row); err != nil {
128			return err
129		}
130		if err = insertToolCalls(ctx, tx, row); err != nil {
131			return err
132		}
133		if err = insertFacets(ctx, tx, row); err != nil {
134			return err
135		}
136	
137		if err = tx.Commit(); err != nil {
138			return fmt.Errorf("commit transaction: %w", err)
139		}
140		return nil
141	}
142	
143	func insertSessionRow(ctx context.Context, tx *sql.Tx, row SessionRow) error {
144		hasSummary := 0
145		if row.HasSummary {
146			hasSummary = 1
147		}
148		hasFacets := 0
149		if row.HasFacets || !isEmptyFacets(row.Facets) {
150			hasFacets = 1
151		}
152		_, err := tx.ExecContext(ctx, `
153			INSERT INTO sessions (
154				checkpoint_id, session_id, session_index,
155				agent, model, branch, owner_name, owner_email, created_at,
156				input_tokens, cache_tokens, output_tokens, total_tokens,
157				api_call_count, duration_ms, turn_count,
158				intent, outcome, agent_percentage,
159				overall_score, score_token_efficiency, score_first_pass,
160				score_friction, score_focus, has_summary, has_facets
161			) VALUES (
162				?, ?, ?,
163				?, ?, ?, ?, ?, ?,
164				?, ?, ?, ?,
165				?, ?, ?,
166				?, ?, ?,
167				?, ?, ?,
168				?, ?, ?, ?
169			)`,
170			row.CheckpointID, row.SessionID, row.SessionIndex,
171			nullableString(row.Agent), nullableString(row.Model), nullableString(row.Branch),
172			nullableString(row.OwnerName), nullableString(row.OwnerEmail),
173			row.CreatedAt.UTC().Format(time.RFC3339),
174			row.InputTokens, row.CacheTokens, row.OutputTokens, row.TotalTokens,
175			row.APICallCount, row.DurationMs, row.TurnCount,
176			nullableString(row.Intent), nullableString(row.Outcome), row.AgentPct,
177			row.OverallScore, row.ScoreTokenEff,
178			row.ScoreFirstPass, row.ScoreFriction,
179			row.ScoreFocus, hasSummary, hasFacets,
180		)
181		if err != nil {
182			return fmt.Errorf("insert session row: %w", err)
183		}
184		return nil
185	}
186	
187	func insertFilesTouched(ctx context.Context, tx *sql.Tx, row SessionRow) error {
188		for _, f := range row.FilesTouched {
189			if _, err := tx.ExecContext(ctx,
190				"INSERT INTO files_touched (checkpoint_id, session_index, file_path) VALUES (?, ?, ?)",
191				row.CheckpointID, row.SessionIndex, f,
192			); err != nil {
193				return fmt.Errorf("insert files_touched: %w", err)
194			}
195		}
196		return nil
197	}
198	
199	func insertFriction(ctx context.Context, tx *sql.Tx, row SessionRow) error {
200		for _, f := range row.Friction {
201			if _, err := tx.ExecContext(ctx,
202				"INSERT INTO friction (checkpoint_id, session_index, text) VALUES (?, ?, ?)",
203				row.CheckpointID, row.SessionIndex, f,
204			); err != nil {
205				return fmt.Errorf("insert friction: %w", err)
206			}
207		}
208		return nil
209	}
210	
211	func insertLearnings(ctx context.Context, tx *sql.Tx, row SessionRow) error {
212		for _, l := range row.Learnings {
213			if _, err := tx.ExecContext(ctx,
214				"INSERT INTO learnings (checkpoint_id, session_index, scope, finding, path) VALUES (?, ?, ?, ?, ?)",
215				row.CheckpointID, row.SessionIndex, l.Scope, l.Finding, nullableString(l.Path),
216			); err != nil {
217				return fmt.Errorf("insert learnings: %w", err)
218			}
219		}
220		return nil
221	}
222	
223	func insertToolCalls(ctx context.Context, tx *sql.Tx, row SessionRow) error {
224		for tool, count := range row.ToolCounts {
225			if _, err := tx.ExecContext(ctx,
226				"INSERT INTO tool_calls (checkpoint_id, session_index, tool_name, count) VALUES (?, ?, ?, ?)",
227				row.CheckpointID, row.SessionIndex, tool, count,
228			); err != nil {
229				return fmt.Errorf("insert tool_calls: %w", err)
230			}
231		}
232		return nil
233	}
234	
235	func insertFacets(ctx context.Context, tx *sql.Tx, row SessionRow) error {
236		for _, instruction := range row.Facets.RepeatedUserInstructions {
237			if _, err := tx.ExecContext(ctx,
238				`INSERT INTO repeated_user_instructions (checkpoint_id, session_index, instruction, evidence)
239				 VALUES (?, ?, ?, ?)`,
240				row.CheckpointID, row.SessionIndex, instruction.Instruction, joinEvidence(instruction.Evidence),
241			); err != nil {
242				return fmt.Errorf("insert repeated_user_instructions: %w", err)
243			}
244		}
245		for _, signal := range row.Facets.MissingContext {
246			if _, err := tx.ExecContext(ctx,
247				`INSERT INTO missing_context_signals (checkpoint_id, session_index, item, evidence)
248				 VALUES (?, ?, ?, ?)`,
249				row.CheckpointID, row.SessionIndex, signal.Item, joinEvidence(signal.Evidence),
250			); err != nil {
251				return fmt.Errorf("insert missing_context_signals: %w", err)
252			}
253		}
254		for _, loop := range row.Facets.FailureLoops {
255			if _, err := tx.ExecContext(ctx,
256				`INSERT INTO failure_loops (checkpoint_id, session_index, description, count, evidence)
257				 VALUES (?, ?, ?, ?, ?)`,
258				row.CheckpointID, row.SessionIndex, loop.Description, loop.Count, joinEvidence(loop.Evidence),
259			); err != nil {
260				return fmt.Errorf("insert failure_loops: %w", err)
261			}
262		}
263		for _, signal := range row.Facets.SkillSignals {
264			if _, err := tx.ExecContext(ctx,
265				`INSERT INTO skill_signals (checkpoint_id, session_index, skill_name, skill_path, friction, missing_instruction)
266				 VALUES (?, ?, ?, ?, ?, ?)`,
267				row.CheckpointID, row.SessionIndex, signal.SkillName, nullableString(signal.SkillPath),
268				joinEvidence(signal.Friction), nullableString(signal.MissingInstruction),
269			); err != nil {
270				return fmt.Errorf("insert skill_signals: %w", err)
271			}
272		}
273		return nil
274	}
275	
276	// UpdateSessionSummary updates an existing session row with summary-derived data
277	// (intent, outcome, scores, friction, learnings) and sets has_summary = 1.
278	func (idb *InsightsDB) UpdateSessionSummary(ctx context.Context, row SessionRow) error {
279		tx, err := idb.db.BeginTx(ctx, nil)
280		if err != nil {
281			return fmt.Errorf("begin transaction: %w", err)
282		}
283		defer func() {
284			if err != nil {
285				_ = tx.Rollback() //nolint:errcheck // Rollback after failed tx; error is irrelevant
286			}
287		}()
288	
289		_, err = tx.ExecContext(ctx, `
290			UPDATE sessions SET
291				intent = ?, outcome = ?,
292				overall_score = ?, score_token_efficiency = ?, score_first_pass = ?,
293				score_friction = ?, score_focus = ?, has_summary = 1
294			WHERE checkpoint_id = ? AND session_index = ?`,
295			nullableString(row.Intent), nullableString(row.Outcome),
296			row.OverallScore, row.ScoreTokenEff, row.ScoreFirstPass,
297			row.ScoreFriction, row.ScoreFocus,
298			row.CheckpointID, row.SessionIndex,
299		)
300		if err != nil {
301			return fmt.Errorf("update session summary: %w", err)
302		}
303	
304		// Delete old friction/learnings and re-insert.
305		for _, table := range []string{"friction", "learnings"} {
306			if _, err = tx.ExecContext(ctx,
307				"DELETE FROM "+table+" WHERE checkpoint_id = ? AND session_index = ?", //nolint:gosec // table name is hardcoded
